-- Real plain Client schema 83 from fef7846c402a05c52c2d105aa10af48ac3724037.
-- Generated by executing historical migrateClientDb and its historical relative imports.
-- sqlite_master DDL only; virtual tables create their own FTS shadow tables.
-- Initial application data is only meta.event_seq=0; fixtures add isolated test history.
PRAGMA foreign_keys=OFF;
BEGIN;
CREATE TABLE code_attribution_outbox (
      id TEXT PRIMARY KEY,
      source_batch_id TEXT NOT NULL UNIQUE,
      workspace_id TEXT NOT NULL,
      instance_id TEXT NOT NULL,
      repository TEXT NOT NULL,
      commit_sha TEXT NOT NULL,
      content_sha256 TEXT NOT NULL,
      payload_json TEXT NOT NULL,
      association_id TEXT NOT NULL,
      association_expires_at INTEGER NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('pending', 'leased', 'failed')),
      attempt_count INTEGER NOT NULL DEFAULT 0 CHECK(attempt_count >= 0),
      available_at INTEGER NOT NULL,
      lease_owner TEXT NULL,
      lease_expires_at INTEGER NULL,
      last_error_code TEXT NULL,
      last_error_message TEXT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
      FOREIGN KEY(instance_id) REFERENCES orch_instances(id) ON DELETE CASCADE,
      UNIQUE(workspace_id, instance_id, repository, commit_sha)
    );
CREATE TABLE code_attribution_retention_tasks (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL,
      instance_id TEXT NOT NULL,
      repository_path TEXT NOT NULL,
      repository TEXT NOT NULL,
      commit_sha TEXT NOT NULL,
      file_path TEXT NOT NULL,
      file_identity_sha256 TEXT NOT NULL,
      retained_lines_json TEXT NOT NULL,
      retained_ai_added_lines INTEGER NOT NULL CHECK(retained_ai_added_lines >= 0),
      window_days INTEGER NOT NULL CHECK(window_days IN (7, 30)),
      due_at INTEGER NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('pending', 'leased', 'failed')),
      attempt_count INTEGER NOT NULL DEFAULT 0 CHECK(attempt_count >= 0),
      available_at INTEGER NOT NULL,
      lease_owner TEXT NULL,
      lease_expires_at INTEGER NULL,
      last_error_code TEXT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
      FOREIGN KEY(instance_id) REFERENCES orch_instances(id) ON DELETE CASCADE,
      UNIQUE(workspace_id, instance_id, repository, commit_sha, file_identity_sha256, window_days)
    );
CREATE TABLE controlled_experiment_runs (
      id TEXT PRIMARY KEY,
      experiment_id TEXT NOT NULL,
      assignment_id TEXT NOT NULL,
      sample_id TEXT NOT NULL,
      variant_key TEXT NOT NULL CHECK (variant_key IN ('baseline', 'candidate')),
      attempt_no INTEGER NOT NULL CHECK (attempt_no IN (1, 2)),
      snapshot_id TEXT NOT NULL,
      dispatch_token_sha256 TEXT NOT NULL,
      status TEXT NOT NULL CHECK (status IN ('dispatched', 'running', 'cancel_requested', 'succeeded', 'failed', 'timed_out', 'cancelled')),
      status_version INTEGER NOT NULL DEFAULT 0,
      client_turn_id TEXT NOT NULL,
      engine TEXT NOT NULL CHECK (engine IN ('claude', 'codex')),
      engine_session_id TEXT NULL,
      engine_turn_id TEXT NULL,
      deadline_at INTEGER NOT NULL,
      started_at INTEGER NULL,
      completed_at INTEGER NULL,
      output_text TEXT NULL,
      output_sha256 TEXT NULL,
      input_tokens INTEGER NULL,
      output_tokens INTEGER NULL,
      cached_input_tokens INTEGER NULL,
      cache_creation_input_tokens INTEGER NULL,
      total_tokens INTEGER NULL,
      estimated_cost_micros INTEGER NULL,
      usage_accounting_status TEXT NOT NULL CHECK (usage_accounting_status IN ('pending', 'complete')),
      event_log_json TEXT NOT NULL DEFAULT '[]',
      error_code TEXT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      UNIQUE(experiment_id, assignment_id, variant_key, attempt_no),
      FOREIGN KEY(snapshot_id) REFERENCES controlled_experiment_snapshots(id) ON DELETE RESTRICT
    );
CREATE TABLE controlled_experiment_snapshots (
      id TEXT PRIMARY KEY,
      experiment_id TEXT NOT NULL,
      freeze_revision INTEGER NOT NULL,
      workspace_id TEXT NOT NULL,
      sample_id TEXT NOT NULL,
      evaluation_item_id TEXT NOT NULL,
      source_instance_id TEXT NOT NULL,
      node_id TEXT NOT NULL,
      prompt_snapshot_id TEXT NOT NULL,
      ordinal INTEGER NOT NULL,
      variant_key TEXT NOT NULL CHECK (variant_key IN ('baseline', 'candidate')),
      engine TEXT NOT NULL CHECK (engine IN ('claude', 'codex')),
      model TEXT NOT NULL,
      effort TEXT NULL,
      prompt_envelope_json TEXT NOT NULL,
      system_message TEXT NOT NULL,
      developer_message TEXT NULL,
      user_message TEXT NOT NULL,
      artifact_input_json TEXT NOT NULL,
      input_sha256 TEXT NOT NULL,
      config_sha256 TEXT NOT NULL,
      prompt_definition_sha256 TEXT NOT NULL,
      price_snapshot_json TEXT NOT NULL,
      price_snapshot_sha256 TEXT NOT NULL,
      freeze_digest TEXT NOT NULL,
      per_run_timeout_ms INTEGER NOT NULL,
      created_at INTEGER NOT NULL,
      UNIQUE(experiment_id, freeze_revision, sample_id, variant_key),
      UNIQUE(experiment_id, freeze_revision, evaluation_item_id, variant_key)
    );
CREATE TABLE conversation_diff_snapshots (
      thread_id TEXT NOT NULL,
      diff_key TEXT NOT NULL,
      event_seq INTEGER NOT NULL UNIQUE,
      diff_text TEXT NOT NULL,
      diff_sha256 TEXT NOT NULL,
      diff_bytes INTEGER NOT NULL CHECK (diff_bytes >= 0),
      updated_at INTEGER NOT NULL,
      PRIMARY KEY(thread_id, diff_key),
      FOREIGN KEY(thread_id) REFERENCES threads(id) ON DELETE CASCADE,
      FOREIGN KEY(event_seq) REFERENCES conversation_events(seq) ON DELETE CASCADE
    );
CREATE TABLE conversation_events (
      seq INTEGER PRIMARY KEY,
      thread_id TEXT NOT NULL,
      workspace_id TEXT NOT NULL,
      engine TEXT NOT NULL,
      type TEXT NOT NULL,
      event_json TEXT NOT NULL,
      ts INTEGER NOT NULL,
      FOREIGN KEY(thread_id) REFERENCES threads(id) ON DELETE CASCADE
    );
CREATE TABLE conversation_items (
      item_id TEXT PRIMARY KEY,
      thread_id TEXT NOT NULL,
      kind TEXT NOT NULL,
      data_json TEXT NOT NULL,
      sort_key INTEGER NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(thread_id) REFERENCES threads(id) ON DELETE CASCADE
    );
CREATE TABLE dingtalk_reminder_notifications (
      notification_key TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL,
      source_type TEXT NOT NULL CHECK(source_type IN ('chat', 'orchestration')),
      target_id TEXT NOT NULL,
      title TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('pending', 'sent', 'failed')),
      attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts >= 0),
      error_message TEXT NOT NULL DEFAULT '',
      sent_at INTEGER NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE
    );
CREATE TABLE engine_custom_models (
      id TEXT PRIMARY KEY,
      engine TEXT NOT NULL CHECK(engine IN ('claude', 'codex')),
      provider_id TEXT NOT NULL,
      model_id TEXT NOT NULL,
      display_name TEXT NOT NULL,
      context_window INTEGER NULL,
      max_context_window INTEGER NULL,
      input_modalities_json TEXT NULL,
      reasoning_efforts_json TEXT NULL,
      default_reasoning_effort TEXT NULL,
      supports_fast_mode INTEGER NOT NULL DEFAULT 0,
      supports_1m_context INTEGER NOT NULL DEFAULT 0,
      enabled INTEGER NOT NULL DEFAULT 1,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      UNIQUE(engine, model_id)
    );
CREATE TABLE engine_events (
      seq INTEGER PRIMARY KEY,
      thread_id TEXT NOT NULL,
      workspace_id TEXT NOT NULL,
      engine TEXT NOT NULL,
      type TEXT NOT NULL,
      event_json TEXT NOT NULL,
      ts INTEGER NOT NULL,
      FOREIGN KEY(thread_id) REFERENCES threads(id) ON DELETE CASCADE
    );
CREATE TABLE engine_keys (
      id TEXT PRIMARY KEY,
      label TEXT NOT NULL,
      engine TEXT NOT NULL,
      provider_id TEXT NULL,
      api_key TEXT NOT NULL,
      base_url TEXT NULL,
      is_active INTEGER NOT NULL DEFAULT 0,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );
CREATE TABLE file_blobs (
      blob_id TEXT PRIMARY KEY,
      byte_len INTEGER NOT NULL,
      encoding TEXT NOT NULL,
      data BLOB NOT NULL,
      created_at INTEGER NOT NULL
    );
CREATE TABLE meta (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );
CREATE TABLE notes (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL,
      title TEXT NOT NULL,
      content TEXT NOT NULL DEFAULT '',
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE
    );
CREATE TABLE orch_artifact_fields (
      id TEXT PRIMARY KEY,
      artifact_id TEXT NOT NULL,
      instance_id TEXT NOT NULL,
      node_id TEXT NOT NULL,
      result_name TEXT NOT NULL,
      field_key TEXT NOT NULL,
      label TEXT NULL,
      value_type TEXT NOT NULL,
      value_json TEXT NOT NULL,
      value_preview TEXT NULL,
      required INTEGER NOT NULL DEFAULT 0,
      source TEXT NOT NULL,
      validation_status TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(artifact_id) REFERENCES orch_artifacts(id) ON DELETE CASCADE,
      UNIQUE(artifact_id, field_key)
    );
CREATE TABLE orch_artifact_files (
      id TEXT PRIMARY KEY,
      artifact_id TEXT NOT NULL,
      file_key TEXT NULL,
      file_role TEXT NOT NULL DEFAULT 'contract',
      format TEXT NULL,
      contract_key TEXT NULL,
      summary TEXT NULL,
      validation_status TEXT NULL,
      rel_path TEXT NOT NULL,
      staging_path TEXT NULL,
      published_path TEXT NULL,
      status TEXT NOT NULL,
      content_hash TEXT NOT NULL,
      size_bytes INTEGER NOT NULL DEFAULT 0,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(artifact_id) REFERENCES orch_artifacts(id) ON DELETE CASCADE
    );
CREATE TABLE orch_artifacts (
      id TEXT PRIMARY KEY,
      instance_id TEXT NOT NULL,
      node_id TEXT NOT NULL,
      kind TEXT NOT NULL,
      version INTEGER NOT NULL DEFAULT 1,
      title TEXT NOT NULL DEFAULT '',
      schema_ref TEXT NULL,
      status TEXT NOT NULL DEFAULT 'draft',
      content_json TEXT NOT NULL,
      metadata_json TEXT NULL,
      persistence_mode TEXT NULL,
      payload_mode TEXT NULL,
      workspace_status TEXT NULL,
      workspace_base_dir TEXT NULL,
      staging_path TEXT NULL,
      published_path TEXT NULL,
      content_hash TEXT NULL,
      manifest_json TEXT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(instance_id) REFERENCES orch_instances(id) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_bundle_sync (
      workspace_id TEXT NOT NULL,
      bundle_id TEXT NOT NULL,
      bundle_version INTEGER NOT NULL,
      synced_at INTEGER NOT NULL,
      PRIMARY KEY (workspace_id, bundle_id),
      FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_cache_entries (
      context_key TEXT NOT NULL,
      asset_type TEXT NOT NULL
        CHECK (typeof(asset_type) = 'text'
          AND asset_type IN ('role', 'workflow', 'knowledge_bundle', 'toolset', 'skill')),
      asset_id TEXT NOT NULL
        CHECK (typeof(asset_id) = 'text' AND asset_id = trim(asset_id) AND length(asset_id) > 0),
      server_revision INTEGER NOT NULL
        CHECK (typeof(server_revision) = 'integer' AND server_revision BETWEEN 1 AND 9007199254740991),
      definition_json TEXT NOT NULL
        CHECK (typeof(definition_json) = 'text'
          AND json_valid(definition_json) AND json_type(definition_json) = 'object'),
      content_hash TEXT NOT NULL
        CHECK (typeof(content_hash) = 'text'
          AND length(content_hash) = 64 AND content_hash NOT GLOB '*[^0-9a-f]*'),
      source_scope_type TEXT NOT NULL
        CHECK (typeof(source_scope_type) = 'text'
          AND source_scope_type IN ('builtin', 'user', 'shared_workspace')),
      sync_change_seq INTEGER NOT NULL
        CHECK (typeof(sync_change_seq) = 'integer' AND sync_change_seq BETWEEN 0 AND 9007199254740991),
      PRIMARY KEY(context_key, asset_type, asset_id),
      FOREIGN KEY(context_key) REFERENCES orch_asset_cache_state(context_key) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_cache_group_assignments (
      context_key TEXT NOT NULL,
      asset_type TEXT NOT NULL
        CHECK (typeof(asset_type) = 'text'
          AND asset_type IN ('role', 'workflow', 'knowledge_bundle', 'toolset', 'skill')),
      asset_id TEXT NOT NULL
        CHECK (typeof(asset_id) = 'text' AND asset_id = trim(asset_id) AND length(asset_id) > 0),
      group_id TEXT NOT NULL
        CHECK (typeof(group_id) = 'text' AND group_id = trim(group_id) AND length(group_id) > 0),
      sync_change_seq INTEGER NOT NULL
        CHECK (typeof(sync_change_seq) = 'integer' AND sync_change_seq BETWEEN 0 AND 9007199254740991),
      PRIMARY KEY(context_key, asset_type, asset_id),
      FOREIGN KEY(context_key, asset_type, asset_id)
        REFERENCES orch_asset_cache_entries(context_key, asset_type, asset_id) ON DELETE CASCADE,
      FOREIGN KEY(context_key, asset_type, group_id)
        REFERENCES orch_asset_cache_groups(context_key, asset_type, group_id) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_cache_groups (
      context_key TEXT NOT NULL,
      asset_type TEXT NOT NULL
        CHECK (typeof(asset_type) = 'text'
          AND asset_type IN ('role', 'workflow', 'knowledge_bundle', 'toolset', 'skill')),
      group_id TEXT NOT NULL
        CHECK (typeof(group_id) = 'text' AND group_id = trim(group_id) AND length(group_id) > 0),
      name TEXT NOT NULL
        CHECK (typeof(name) = 'text' AND name = trim(name) AND length(name) BETWEEN 1 AND 60),
      created_at INTEGER NOT NULL
        CHECK (typeof(created_at) = 'integer' AND created_at BETWEEN 0 AND 9007199254740991),
      updated_at INTEGER NOT NULL
        CHECK (typeof(updated_at) = 'integer' AND updated_at BETWEEN created_at AND 9007199254740991),
      sync_change_seq INTEGER NOT NULL
        CHECK (typeof(sync_change_seq) = 'integer' AND sync_change_seq BETWEEN 0 AND 9007199254740991),
      PRIMARY KEY(context_key, asset_type, group_id),
      FOREIGN KEY(context_key) REFERENCES orch_asset_cache_state(context_key) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_cache_skill_files (
      context_key TEXT NOT NULL,
      asset_type TEXT NOT NULL DEFAULT 'skill'
        CHECK (typeof(asset_type) = 'text' AND asset_type = 'skill'),
      skill_id TEXT NOT NULL
        CHECK (typeof(skill_id) = 'text' AND skill_id = trim(skill_id) AND length(skill_id) > 0),
      server_revision INTEGER NOT NULL
        CHECK (typeof(server_revision) = 'integer' AND server_revision BETWEEN 1 AND 9007199254740991),
      rel_path TEXT NOT NULL
        CHECK (typeof(rel_path) = 'text' AND rel_path = trim(rel_path) AND length(rel_path) > 0),
      kind TEXT NOT NULL
        CHECK (typeof(kind) = 'text' AND kind IN ('skill-md', 'script', 'reference', 'asset', 'metadata')),
      content_text TEXT NULL,
      content_bytes BLOB NULL,
      content_type TEXT NOT NULL
        CHECK (typeof(content_type) = 'text'
          AND content_type = trim(content_type) AND length(content_type) > 0),
      size_bytes INTEGER NOT NULL
        CHECK (typeof(size_bytes) = 'integer' AND size_bytes BETWEEN 0 AND 8388608),
      sha256 TEXT NOT NULL
        CHECK (typeof(sha256) = 'text'
          AND length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
      PRIMARY KEY(context_key, skill_id, rel_path),
      CHECK (
        (typeof(content_text) = 'text' AND content_bytes IS NULL
          AND length(CAST(content_text AS BLOB)) = size_bytes)
        OR
        (content_text IS NULL AND typeof(content_bytes) = 'blob'
          AND length(content_bytes) = size_bytes)
      ),
      FOREIGN KEY(context_key, asset_type, skill_id, server_revision)
        REFERENCES orch_asset_cache_entries(context_key, asset_type, asset_id, server_revision)
        ON DELETE CASCADE
    );
CREATE TABLE orch_asset_cache_state (
      context_key TEXT PRIMARY KEY
        CHECK (typeof(context_key) = 'text' AND context_key = trim(context_key) AND length(context_key) > 0),
      authority_epoch INTEGER NOT NULL
        CHECK (typeof(authority_epoch) = 'integer' AND authority_epoch BETWEEN 0 AND 9007199254740991),
      last_change_seq INTEGER NOT NULL DEFAULT 0
        CHECK (typeof(last_change_seq) = 'integer' AND last_change_seq BETWEEN 0 AND 9007199254740991),
      snapshot_hash TEXT NULL
        CHECK (snapshot_hash IS NULL OR (
          typeof(snapshot_hash) = 'text'
          AND length(snapshot_hash) = 64 AND snapshot_hash NOT GLOB '*[^0-9a-f]*'
        )),
      last_success_at INTEGER NULL
        CHECK (last_success_at IS NULL OR (
          typeof(last_success_at) = 'integer' AND last_success_at BETWEEN 0 AND 9007199254740991
        )),
      sync_status TEXT NOT NULL
        CHECK (typeof(sync_status) = 'text' AND sync_status IN ('ready', 'pending', 'stale', 'failed')),
      last_error_code TEXT NULL
        CHECK (last_error_code IS NULL OR (
          typeof(last_error_code) = 'text'
          AND last_error_code = trim(last_error_code) AND length(last_error_code) > 0
        )),
      updated_at INTEGER NOT NULL
        CHECK (typeof(updated_at) = 'integer' AND updated_at BETWEEN 0 AND 9007199254740991),
      CHECK ((snapshot_hash IS NULL) = (last_success_at IS NULL)),
      CHECK (sync_status <> 'ready' OR (
        snapshot_hash IS NOT NULL AND last_success_at IS NOT NULL AND last_error_code IS NULL
      )),
      CHECK (sync_status <> 'failed' OR last_error_code IS NOT NULL)
    );
CREATE TABLE orch_asset_cache_sync_pages (
      run_id TEXT NOT NULL,
      page_index INTEGER NOT NULL
        CHECK (typeof(page_index) = 'integer' AND page_index BETWEEN 0 AND 9007199254740991),
      previous_snapshot_hash TEXT NULL
        CHECK (previous_snapshot_hash IS NULL OR (
          typeof(previous_snapshot_hash) = 'text'
          AND length(previous_snapshot_hash) = 64 AND previous_snapshot_hash NOT GLOB '*[^0-9a-f]*'
        )),
      from_seq INTEGER NOT NULL
        CHECK (typeof(from_seq) = 'integer' AND from_seq BETWEEN 0 AND 9007199254740991),
      page_to_seq INTEGER NOT NULL
        CHECK (typeof(page_to_seq) = 'integer' AND page_to_seq BETWEEN from_seq AND 9007199254740991),
      page_hash TEXT NOT NULL
        CHECK (typeof(page_hash) = 'text'
          AND length(page_hash) = 64 AND page_hash NOT GLOB '*[^0-9a-f]*'),
      snapshot_hash TEXT NOT NULL
        CHECK (typeof(snapshot_hash) = 'text'
          AND length(snapshot_hash) = 64 AND snapshot_hash NOT GLOB '*[^0-9a-f]*'),
      payload_json TEXT NOT NULL
        CHECK (typeof(payload_json) = 'text'
          AND json_valid(payload_json) AND json_type(payload_json) = 'object'),
      payload_bytes INTEGER NOT NULL
        CHECK (typeof(payload_bytes) = 'integer' AND payload_bytes BETWEEN 0 AND 4194304
          AND length(CAST(payload_json AS BLOB)) = payload_bytes),
      is_final INTEGER NOT NULL
        CHECK (typeof(is_final) = 'integer' AND is_final IN (0, 1)),
      created_at INTEGER NOT NULL
        CHECK (typeof(created_at) = 'integer' AND created_at BETWEEN 0 AND 9007199254740991),
      PRIMARY KEY(run_id, page_index),
      CHECK ((page_index = 0 AND previous_snapshot_hash IS NULL)
        OR (page_index > 0 AND previous_snapshot_hash IS NOT NULL)),
      FOREIGN KEY(run_id) REFERENCES orch_asset_cache_sync_runs(run_id) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_cache_sync_runs (
      run_id TEXT PRIMARY KEY
        CHECK (typeof(run_id) = 'text' AND run_id = trim(run_id) AND length(run_id) > 0),
      context_key TEXT NOT NULL
        CHECK (typeof(context_key) = 'text' AND context_key = trim(context_key) AND length(context_key) > 0),
      authority_epoch INTEGER NOT NULL
        CHECK (typeof(authority_epoch) = 'integer' AND authority_epoch BETWEEN 0 AND 9007199254740991),
      mode TEXT NOT NULL CHECK (typeof(mode) = 'text' AND mode IN ('full', 'delta')),
      sync_from_seq INTEGER NOT NULL
        CHECK (typeof(sync_from_seq) = 'integer' AND sync_from_seq BETWEEN 0 AND 9007199254740991),
      snapshot_to_seq INTEGER NOT NULL
        CHECK (typeof(snapshot_to_seq) = 'integer'
          AND snapshot_to_seq BETWEEN sync_from_seq AND 9007199254740991),
      next_page_index INTEGER NOT NULL DEFAULT 0
        CHECK (typeof(next_page_index) = 'integer' AND next_page_index BETWEEN 0 AND 9007199254740991),
      last_page_to_seq INTEGER NULL
        CHECK (last_page_to_seq IS NULL OR (
          typeof(last_page_to_seq) = 'integer'
          AND last_page_to_seq BETWEEN sync_from_seq AND snapshot_to_seq
        )),
      last_snapshot_hash TEXT NULL
        CHECK (last_snapshot_hash IS NULL OR (
          typeof(last_snapshot_hash) = 'text'
          AND length(last_snapshot_hash) = 64 AND last_snapshot_hash NOT GLOB '*[^0-9a-f]*'
        )),
      status TEXT NOT NULL
        CHECK (typeof(status) = 'text' AND status IN ('collecting', 'ready')),
      total_payload_bytes INTEGER NOT NULL DEFAULT 0
        CHECK (typeof(total_payload_bytes) = 'integer'
          AND total_payload_bytes BETWEEN 0 AND 9007199254740991),
      created_at INTEGER NOT NULL
        CHECK (typeof(created_at) = 'integer' AND created_at BETWEEN 0 AND 9007199254740991),
      updated_at INTEGER NOT NULL
        CHECK (typeof(updated_at) = 'integer' AND updated_at BETWEEN created_at AND 9007199254740991),
      CHECK ((last_page_to_seq IS NULL) = (last_snapshot_hash IS NULL)),
      CHECK ((next_page_index = 0) = (last_snapshot_hash IS NULL)),
      CHECK (status <> 'ready' OR (
        next_page_index > 0 AND last_page_to_seq = snapshot_to_seq
      ))
    );
CREATE TABLE orch_asset_drafts (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL,
      asset_kind TEXT NOT NULL,
      mode TEXT NOT NULL,
      status TEXT NOT NULL,
      target_asset_id TEXT NULL,
      base_version_id TEXT NULL,
      source_job_id TEXT NOT NULL,
      prompt TEXT NOT NULL,
      payload_json TEXT NOT NULL,
      validation_issues_json TEXT NULL,
      rationale TEXT NULL,
      engine_info_json TEXT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
      FOREIGN KEY(source_job_id) REFERENCES orch_asset_generation_jobs(id) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_generation_jobs (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL,
      asset_kind TEXT NOT NULL,
      mode TEXT NOT NULL,
      status TEXT NOT NULL,
      target_asset_id TEXT NULL,
      client_request_id TEXT NULL,
      base_version_id TEXT NULL,
      draft_id TEXT NULL,
      thread_id TEXT NULL,
      prompt TEXT NOT NULL,
      request_json TEXT NULL,
      interaction_json TEXT NULL,
      progress_json TEXT NULL,
      failure_json TEXT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_group_assignments (
      workspace_id TEXT NOT NULL,
      asset_type TEXT NOT NULL,
      asset_id TEXT NOT NULL,
      group_id TEXT NOT NULL,
      updated_at INTEGER NOT NULL,
      PRIMARY KEY(workspace_id, asset_type, asset_id),
      FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
      FOREIGN KEY(group_id) REFERENCES orch_asset_groups(id) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_groups (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL,
      asset_type TEXT NOT NULL,
      name TEXT NOT NULL,
      name_key TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_job_events (
      id TEXT PRIMARY KEY,
      job_id TEXT NOT NULL,
      type TEXT NOT NULL,
      payload_json TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      FOREIGN KEY(job_id) REFERENCES orch_asset_generation_jobs(id) ON DELETE CASCADE
    );
CREATE TABLE orch_asset_legacy_authority_state (
        workspace_id TEXT PRIMARY KEY
          CHECK (typeof(workspace_id) = 'text'
            AND workspace_id = trim(workspace_id)
            AND length(workspace_id) BETWEEN 1 AND 512),
        recorded_at INTEGER NOT NULL
          CHECK (typeof(recorded_at) = 'integer' AND recorded_at BETWEEN 0 AND 9007199254740991),
        FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE
      );
CREATE TABLE orch_asset_migration_lock_state (
      singleton_key INTEGER PRIMARY KEY
        CHECK (typeof(singleton_key) = 'integer' AND singleton_key = 1),
      local_migration_id TEXT NOT NULL
        CHECK (typeof(local_migration_id) = 'text'
          AND local_migration_id = trim(local_migration_id)
          AND length(local_migration_id) BETWEEN 1 AND 512),
      status TEXT NOT NULL
        CHECK (typeof(status) = 'text' AND status IN ('frozen_local', 'batch_bound')),
      migration_mode TEXT NOT NULL
        CHECK (typeof(migration_mode) = 'text' AND migration_mode IN ('initial', 'late_import')),
      asset_context_json TEXT NOT NULL
        CHECK (typeof(asset_context_json) = 'text'
          AND length(CAST(asset_context_json AS BLOB)) BETWEEN 1 AND 2048
          AND json_valid(asset_context_json) AND json_type(asset_context_json) = 'object'),
      local_workspace_ids_json TEXT NOT NULL
        CHECK (typeof(local_workspace_ids_json) = 'text'
          AND length(CAST(local_workspace_ids_json AS BLOB)) BETWEEN 1 AND 5242880
          AND json_valid(local_workspace_ids_json) AND json_type(local_workspace_ids_json) = 'array'
          AND json_array_length(local_workspace_ids_json) BETWEEN 1 AND 10000),
      source_snapshot_hash TEXT NOT NULL
        CHECK (typeof(source_snapshot_hash) = 'text'
          AND length(source_snapshot_hash) = 64
          AND source_snapshot_hash NOT GLOB '*[^0-9a-f]*'),
      expected_asset_count INTEGER NOT NULL
        CHECK (typeof(expected_asset_count) = 'integer' AND expected_asset_count BETWEEN 0 AND 100000),
      expected_group_count INTEGER NOT NULL
        CHECK (typeof(expected_group_count) = 'integer' AND expected_group_count BETWEEN 0 AND 100000),
      expected_assignment_count INTEGER NOT NULL
        CHECK (typeof(expected_assignment_count) = 'integer'
          AND expected_assignment_count BETWEEN 0 AND 100000),
      expected_skill_file_count INTEGER NOT NULL
        CHECK (typeof(expected_skill_file_count) = 'integer'
          AND expected_skill_file_count BETWEEN 0 AND 100000),
      target_scope_id TEXT NULL
        CHECK (target_scope_id IS NULL OR (
          typeof(target_scope_id) = 'text' AND target_scope_id = trim(target_scope_id)
          AND length(target_scope_id) BETWEEN 1 AND 512
        )),
      migration_batch_id TEXT NULL
        CHECK (migration_batch_id IS NULL OR (
          typeof(migration_batch_id) = 'text' AND migration_batch_id = trim(migration_batch_id)
          AND length(migration_batch_id) BETWEEN 1 AND 512
        )),
      locked_at INTEGER NOT NULL
        CHECK (typeof(locked_at) = 'integer' AND locked_at BETWEEN 0 AND 9007199254740991),
      updated_at INTEGER NOT NULL
        CHECK (typeof(updated_at) = 'integer' AND updated_at BETWEEN locked_at AND 9007199254740991),
      group_name_plan_hash TEXT NULL
        CHECK (group_name_plan_hash IS NULL OR (
          typeof(group_name_plan_hash) = 'text' AND length(group_name_plan_hash) = 64
          AND group_name_plan_hash NOT GLOB '*[^0-9a-f]*'
        )),
      CHECK (
        (status = 'frozen_local' AND target_scope_id IS NULL AND migration_batch_id IS NULL)
        OR
        (status = 'batch_bound' AND target_scope_id IS NOT NULL AND migration_batch_id IS NOT NULL)
      )
    );
